import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'

export default defineConfig({ base: './', plugins: [vue()] })

import { createRouter, createWebHashHistory } from 'vue-router'
import OverviewView from '../views/OverviewView.vue'
import AlertsView from '../views/AlertsView.vue'

export default createRouter({
  history: createWebHashHistory(),
  routes: [
    { path: '/', component: OverviewView },
    { path: '/alerts', component: AlertsView }
  ]
})

:root { font-family: Inter, system-ui, sans-serif; color: #dce6f6; background: #0b1220; }
* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; }
a { color: inherit; text-decoration: none; }
header { height: 70px; padding: 0 max(24px, calc((100% - 1200px) / 2)); display: flex; align-items: center; gap: 36px; background: #101a2c; border-bottom: 1px solid #243149; }
header div { margin-right: auto; display: grid; }
header strong { color: #6ee7b7; }
header span { color: #7887a1; font-size: 12px; }
nav { display: flex; gap: 24px; }
nav a { color: #8190aa; }
nav a.router-link-active { color: #fff; }
main { width: min(1200px, calc(100% - 40px)); margin: 0 auto; padding: 34px 0; }
.topline { display: flex; align-items: end; justify-content: space-between; margin-bottom: 24px; }
h1, h2, p { margin: 0; }
h1 { margin-top: 5px; font-size: 29px; }
h2 { font-size: 16px; }
p, small { color: #7887a1; }
.metrics { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
.metrics article, .panels article, .alert-list { background: #111c30; border: 1px solid #243149; border-radius: 10px; }
.metrics article { display: grid; padding: 19px; gap: 9px; }
.metrics span { color: #8b99b0; }
.metrics strong { font-size: 27px; }
.metrics small { color: #4ade80; }
.panels { display: grid; grid-template-columns: 2fr 1fr; gap: 14px; margin-top: 14px; }
.panels article { padding: 22px; min-height: 350px; }
.chart { height: 290px; }
.donut { width: 170px; aspect-ratio: 1; margin: 30px auto; border: 28px solid #27354b; border-top-color: #4ade80; border-radius: 50%; display: grid; place-content: center; text-align: center; }
.donut strong { font-size: 26px; }
ul { line-height: 2; color: #8998af; }
.alert-list > div { display: flex; align-items: center; gap: 15px; padding: 20px; border-bottom: 1px solid #243149; }
.alert-list > div:last-child { border: 0; }
.alert-list section { flex: 1; }
@media (max-width: 800px) { .metrics { grid-template-columns: repeat(2, 1fr); } .panels { grid-template-columns: 1fr; } nav { display: none; } }
